target.css:
:root {
  --panel: #fffdf7;
  --soft: #f0f5f1;
  --ink: #173c3a;
  --muted: #67807c;
  --line: #d7e2da;
  --teal: #147b76;
  --aqua: #a9ded4;
  --lime: #d8ec86;
  --amber: #efa849;
}

* {
  box-sizing: border-box;
}

h1,
h2,
p,
figure {
  margin: 0;
}

.laundry-panel {
  width: 500px;
  overflow: hidden;
  color: var(--ink);
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 16px 12px;
  border-bottom: 1px solid var(--line);
}

.heading-block {
  display: flex;
  align-items: baseline;
  gap: 9px;
}

.eyebrow {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  line-height: 1.2;
  text-transform: uppercase;
}

h1 {
  font-size: 20px;
  font-weight: 750;
  letter-spacing: -0.04em;
  line-height: 1;
}

.live-badge {
  padding: 5px 9px;
  color: var(--teal);
  background: var(--lime);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 750;
  line-height: 1;
}

.machine-overview {
  display: grid;
  grid-template-columns: 58px 1fr auto;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
}

.machine-icon {
  display: grid;
  width: 58px;
  height: 58px;
  place-items: center;
  background: var(--soft);
  border: 1px solid var(--line);
  border-radius: 14px;
}

.drum {
  display: grid;
  width: 36px;
  height: 36px;
  place-items: center;
  background: var(--aqua);
  border: 4px solid var(--teal);
  border-radius: 50%;
}

.drum-core {
  width: 12px;
  height: 12px;
  background: var(--panel);
  border-radius: 50%;
}

.cycle-copy {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

h2 {
  font-size: 17px;
  font-weight: 750;
  letter-spacing: -0.025em;
  line-height: 1.1;
}

.cycle-note {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.25;
}

.temperature {
  align-self: start;
  padding: 5px 8px;
  color: var(--amber);
  background: var(--soft);
  border-radius: 8px;
  font-size: 13px;
  font-weight: 750;
  line-height: 1;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin: 0 16px;
  background: var(--soft);
  border: 1px solid var(--line);
  border-radius: 12px;
}

.metric {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 9px 12px;
}

.metric + .metric {
  border-left: 1px solid var(--line);
}

.metric p,
.progress-header p {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  line-height: 1.2;
}

.metric strong {
  font-size: 18px;
  font-weight: 750;
  letter-spacing: -0.035em;
  line-height: 1;
}

.metric strong span {
  color: var(--muted);
  font-size: 10px;
  letter-spacing: 0;
}

.progress-section {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 12px 16px;
}

.progress-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.progress-header strong {
  color: var(--teal);
  font-size: 12px;
  line-height: 1;
}

.track {
  display: block;
  height: 7px;
  overflow: hidden;
  background: var(--line);
  border-radius: 999px;
}

.fill {
  display: block;
  width: 72%;
  height: 100%;
  background: var(--teal);
  border-radius: inherit;
}

.panel-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  background: var(--soft);
  border-top: 1px solid var(--line);
}

.panel-footer p {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.2;
}

.dot {
  width: 7px;
  height: 7px;
  background: var(--teal);
  border-radius: 50%;
}

button {
  padding: 7px 10px;
  color: var(--panel);
  background: var(--ink);
  border: 0;
  border-radius: 8px;
  font-size: 11px;
  font-weight: 750;
  line-height: 1;
}

